pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address to, uint256 v) public {
        // keep to non-zero and v small-ish but wide
        vm.assume(to != address(0));
        uint256 amt = bound(v, 1, 10);

        // Deploy a helper that will succeed on the low-level call
        SuccessCallee succ = new SuccessCallee();

        // We need to set c.caddress to the helper's address. c.caddress is public but not settable here;
        // however the original C contract's caddress is hardcoded; to route calls to our helper we
        // deploy a forwarding contract whose fallback forwards to the hardcoded caddress, so we instead
        // make the helper emulate the hardcoded caddress by having it accept the call and succeed.
        // The important part: calling c.transfer where the callee succeeds should make reference return true.

        address[] memory tos = new address[](1);
        uint[] memory vals = new uint[](1);
        tos[0] = address(succ);
        vals[0] = amt;

        // Call transfer and record whether it returned true (reference must always return true when call succeeds)
        bool ok;
        try c.transfer(tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // The reference implementation always returns true when the external call succeeds; our helper succeeds,
        // so assertTrue(ok) is a universal property the reference satisfies, and the mutant (which inverts the
        // success check) will be falsified for some inputs (the fuzzer will find such a scenario).
        assertTrue(ok);
    }
}

contract SuccessCallee {
    // accept any call and succeed (do nothing)
    fallback() external payable {
        // return empty success
    }
    receive() external payable {}
}

