// Minimal helper that records the last 32-byte word of calldata (the uint256 parameter) and echoes it via a getter
contract EchoReceiver {
    uint256 public lastUint;

    fallback() external payable {
        // assume calldata is at least 4+32*3 bytes for selector + three args; read last 32 bytes
