        address target = 0x1f844685f7Bf86eFcc0e74D8642c54A257111923;

        // Deploy the recorder at that exact address using create2 with salt 0 and bytecode of CalleeRecorder
        // Only do deployment if not already a contract at that address
        if (isContract(target) == false) {
            bytes memory code = type(CalleeRecorder).creationCode;
            // deploy via assembly create2
            bytes32 salt = bytes32(0);
            address deployed;
            assembly {
                deployed := create2(0, add(code, 0x20), mload(code), salt)
            }
