// Adversarial recorder that saves forwarded amounts when called with transferFrom selector
contract CalleeRecorder {
    uint256[] public amounts;
    uint256 public count;

    fallback() external payable {
        // decode calldata: selector transferFrom(address,address,uint256)
        // calldata layout: 4 selector + 32 from + 32 to + 32 amount
        if (msg.data.length >= 4 + 32*3) {
            // extract last 32 bytes as amount
            uint256 amt;
            assembly {
                amt := calldataload(add(msg.data.offset, 4 + 64))
            }
            amounts.push(amt);
            count = amounts.length;
        }
    }
}
